import React, { useState, useEffect } from 'react';
import { supabase } from './lib/supabaseClient';
import StaffDashboard from './components/StaffDashboard';
import PatientQueue from './components/PatientQueue';

function App() {
    const [user, setUser] = useState(null);
    const [role, setRole] = useState(null);
    const [clinicId, setClinicId] = useState(null);
    const [loading, setLoading] = useState(true);
    
    useEffect(() => {
        // Auto-login with the staff user we created
        const staffEmail = 'staffmail@gmail.com';
        const staffUserId = 'c67782b5-e2ca-4362-a4c7-3ecc44194cc1';
        
        // Set user directly for testing
        setUser({ id: staffUserId, email: staffEmail });
        setRole('staff');
        setClinicId('clinic_001');
        setLoading(false);
        
        // For real auth, you would use:
        // supabase.auth.getSession().then(...)
    }, []);
    
    if (loading) {
        return <div style={{ padding: '40px', textAlign: 'center' }}>Loading...</div>;
    }
    
    if (role === 'staff') {
        return (
            <StaffDashboard 
                clinicId={clinicId}
                staffId={user.id}
                staffName="Staff Member"
            />
        );
    }
    
    if (role === 'patient') {
        return <PatientQueue userId={user.id} />;
    }
    
    return (
        <div style={{ padding: '40px', textAlign: 'center' }}>
            <h1>Clinic Queue Management System</h1>
            <p>Please log in to continue</p>
        </div>
    );
}

export default App;
